def path_color(g,b1,b2):
    H=len(g);W=len(g[0]); prev={b1:b1}; q=deque([b1]); found=None
    while q:
        r,c=q.popleft()
        if (r,c)==b2: found=(r,c); break
        for di in(-1,0,1):
            for dj in(-1,0,1):
                n=(r+di,c+dj)
                if n==b2: found=n; break
                if 0<=n[0]<H and 0<=n[1]<W and n not in prev: prev[n]=prev[(r,c)]; q.append(n)
    if found is None: return None
    path=[]; cur=b2
    while cur!=b1:
        path.append(cur); cur=prev[cur]
    cols=[g[r][c] for r,c in path]
    cnt=Counter(cols).most_common(2)
    return dict(cnt), len(path)
